using EnigmaLogic.Models;
using EnigmaLogic.Services;
using EnigmaLogic.Services.Cryptography;

namespace Tests.EvaluationHarness;

/// <summary>
/// Test suite and automated evaluation harness benchmarks for <see cref="EnigmaPredictGeminiService"/>
/// as generated by Gemini without any external handholding or manual tuning.
/// </summary>
[TestClass]
public class EnigmaPredictGeminiServiceHarnessTests
{
    public TestContext? TestContext { get; set; }

    // =========================================================================
    // 1. VALIDATION & EDGE-CASE HANDLING
    // =========================================================================

    [TestMethod]
    public async Task CrackAsync_NullOrEmptyCiphertext_ThrowsArgumentException()
    {
        var service = new EnigmaPredictGeminiService();

        await Assert.ThrowsExactlyAsync<ArgumentException>(() => service.CrackAsync(null!));
        await Assert.ThrowsExactlyAsync<ArgumentException>(() => service.CrackAsync(""));
        await Assert.ThrowsExactlyAsync<ArgumentException>(() => service.CrackAsync("   "));
    }

    [TestMethod]
    public async Task CrackAsync_TooFewAlphaCharacters_ThrowsArgumentException()
    {
        var service = new EnigmaPredictGeminiService();

        // Fewer than 4 letters
        await Assert.ThrowsExactlyAsync<ArgumentException>(() => service.CrackAsync("123 !?"));
        await Assert.ThrowsExactlyAsync<ArgumentException>(() => service.CrackAsync("ABC"));
        await Assert.ThrowsExactlyAsync<ArgumentException>(() => service.CrackAsync("!@#$%^&*()"));
    }

    [TestMethod]
    public async Task CrackAsync_CancellationTriggered_ThrowsOperationCanceledException()
    {
        var service = new EnigmaPredictGeminiService();
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsAsync<OperationCanceledException>(async () =>
        {
            await service.CrackAsync("DIESISTEINTESTTEXTFUERCIPHERTEXT", cts.Token);
        });
    }

    [TestMethod]
    public async Task CrackAsync_CancellationTriggeredAfterDelay_ThrowsOperationCanceledException()
    {
        var service = new EnigmaPredictGeminiService();
        using var cts = new CancellationTokenSource(TimeSpan.FromMilliseconds(50));

        await Assert.ThrowsAsync<OperationCanceledException>(async () =>
        {
            // Give a long ciphertext so computation runs long enough to hit the 50ms token cancellation
            string longCipher = new string('A', 500);
            await service.CrackAsync(longCipher, cts.Token);
        });
    }

    // =========================================================================
    // 2. SIMULATION SANITY CHECKS
    // =========================================================================

    [TestMethod]
    public void HistoricalEnigmaVector_AAAAA_ProducesBDZGO()
    {
        var sim = new EnigmaSimService();
        sim.Configure(new EnigmaSettings('A', 'A', 'A', []), RandomSettings: false);

        string output = sim.Process("AAAAA");
        Assert.AreEqual("BDZGO", output);
    }

    // =========================================================================
    // 3. EVALUATION HARNESS BENCHMARK SUITE FOR GEMINI (AS GENERATED)
    // =========================================================================

    [TestMethod]
    public async Task EvaluationHarness_GeminiServiceAsGenerated_RecordsBaselineMetrics()
    {
        var geminiService = new EnigmaPredictGeminiService();
        var candidate = new GeminiCrackCandidate(geminiService, "Gemini-AsGenerated");

        IReadOnlyList<GroundTruthCase> groundTruthCases = GroundTruthDatasetGenerator.CreateStandardBenchmarkSuite();
        var runner = new EnigmaBenchmarkRunner(groundTruthCases);

        string geminiSourcePath = Path.GetFullPath(
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "EnigmaLogic", "Services", "Cryptography", "EnigmaPredictGeminiService.cs"));

        Assert.IsTrue(File.Exists(geminiSourcePath), $"Expected source file at {geminiSourcePath}");

        ModelEvaluationReport report = await runner.EvaluateCandidateAsync(candidate, geminiSourcePath);

        Assert.AreEqual("Gemini-AsGenerated", report.ModelName);
        Assert.AreEqual(groundTruthCases.Count, report.TotalRuns);
        Assert.IsNotNull(report.RunDetails);
        Assert.HasCount(groundTruthCases.Count, report.RunDetails);

        TestContext?.WriteLine("=== Gemini Evaluation Harness Report (As Generated / No Handholding) ===");
        TestContext?.WriteLine($"Model:                          {report.ModelName}");
        TestContext?.WriteLine($"Total Runs:                     {report.TotalRuns}");
        TestContext?.WriteLine($"Successful Runs:                {report.SuccessfulRuns}");
        TestContext?.WriteLine($"Decryption Success Rate (DSR):   {report.DecryptionSuccessRate:P1}");
        TestContext?.WriteLine($"Average CER:                    {report.AverageCharacterErrorRate:P2}");
        TestContext?.WriteLine($"State Reconstruction Acc (SRA): {report.AverageStateReconstructionAccuracy:P1}");
        TestContext?.WriteLine($"  - Rotor Order Accuracy:       {report.AverageStateBreakdown.RotorOrderAccuracy:P1}");
        TestContext?.WriteLine($"  - Rotor Position Accuracy:    {report.AverageStateBreakdown.RotorPositionAccuracy:P1}");
        TestContext?.WriteLine($"  - Ring Setting Accuracy:      {report.AverageStateBreakdown.RingSettingAccuracy:P1}");
        TestContext?.WriteLine($"  - Plugboard Pair Accuracy:    {report.AverageStateBreakdown.PlugboardPairAccuracy:P1}");
        TestContext?.WriteLine($"  - Plugboard Mapping Accuracy: {report.AverageStateBreakdown.PlugboardMappingAccuracy:P1}");
        TestContext?.WriteLine($"Avg Execution Time:             {report.AverageExecutionTime.TotalMilliseconds:F2} ms");
        TestContext?.WriteLine($"Max Execution Time:             {report.MaxExecutionTime.TotalMilliseconds:F2} ms");
        TestContext?.WriteLine($"Avg Allocated Memory:           {report.AverageAllocatedBytes / 1024.0:F2} KB");
        TestContext?.WriteLine($"Peak Allocated Memory:          {report.PeakAllocatedBytes / 1024.0:F2} KB");
        TestContext?.WriteLine($"Edge-Case Pass Rate:            {report.EdgeCasePassRate:P0}");
        TestContext?.WriteLine($"Avg Cyclomatic Complexity:      {report.AverageCyclomaticComplexity:F2} (Max: {report.MaxCyclomaticComplexity})");
        foreach (SingleRunMetrics run in report.RunDetails)
        {
            TestContext?.WriteLine($"  [{run.CaseId}] Match={run.IsExactMatch}, CER={run.CharacterErrorRate:P1}, SRA={run.StateAccuracy.OverallStateAccuracy:P1}, Time={run.ExecutionTime.TotalMilliseconds:F0}ms, Error={run.ErrorMessage ?? "None"}");
        }
    }

    // =========================================================================
    // 4. CODE QUALITY & MCCABE CYCLOMATIC COMPLEXITY
    // =========================================================================

    [TestMethod]
    public void CyclomaticComplexity_GeminiService_ProducesDetailedMethodBreakdown()
    {
        string geminiSourcePath = Path.GetFullPath(
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "EnigmaLogic", "Services", "Cryptography", "EnigmaPredictGeminiService.cs"));

        FileComplexityReport complexityReport = CyclomaticComplexityAnalyzer.AnalyzeFile(geminiSourcePath);

        Assert.IsGreaterThan(5, complexityReport.MethodCount);
        Assert.IsGreaterThan(1.0, complexityReport.AverageCyclomaticComplexity);

        TestContext?.WriteLine(
            $"EnigmaPredictGeminiService.cs: {complexityReport.MethodCount} methods, " +
            $"Avg CC = {complexityReport.AverageCyclomaticComplexity:F2}, " +
            $"Max CC = {complexityReport.MaxCyclomaticComplexity}, " +
            $"Exceeding McCabe (>10) = {complexityReport.MethodsExceedingThreshold}");

        foreach (MethodComplexityMetric method in complexityReport.Methods)
        {
            TestContext?.WriteLine(
                $"  - {method.MethodSignature}: CC = {method.CyclomaticComplexity}" +
                (method.ExceedsMcCabeThreshold ? " [>10]" : ""));
        }
    }
}
